pub fn bin_search(a: &[i32], k: i32) -> bool {
    // We maintain a half-open interval [low, high) in which we search.
    let mut low: usize = 0;
    let mut high: usize = a.len();

    // Standard lower_bound binary search:
    // invariant: all indices < low contain values < k,
    // and all indices >= high contain values >= k
    while low < high {
        let mid = low + (high - low) / 2;
        if a[mid] < k {
            low = mid + 1;
        } else {
            high = mid;
        }
    }

    // After the loop, `low == high` is the smallest index at which a[index] >= k.
    // We return true exactly when that element equals k.
    low < a.len() && a[low] == k
}

